import Link from 'next/link';

export default function Forbidden() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100vh',
      fontFamily: 'system-ui, -apple-system, sans-serif',
      backgroundColor: '#f9f9f9',
      color: '#333'
    }}>
      <h1 style={{ fontSize: '4rem', margin: '0 0 1rem' }}>403</h1>
      <h2 style={{ fontSize: '2rem', margin: '0 0 2rem' }}>Access Forbidden</h2>
      <p style={{ fontSize: '1.2rem', margin: '0 0 2rem', color: '#666' }}>
        You do not have permission to view this page.
      </p>
      <Link 
        href="/"
        style={{
          padding: '0.75rem 1.5rem',
          backgroundColor: '#0070f3',
          color: 'white',
          textDecoration: 'none',
          borderRadius: '4px',
          fontWeight: 'bold',
          transition: 'background-color 0.2s'
        }}
      >
        Return Home
      </Link>
    </div>
  );
}

import { verifyAdmin } from '@/app/lib/auth';
import { forbidden } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>Admin Dashboard</h1>
      <div style={{ 
        padding: '1.5rem', 
        backgroundColor: '#e6fffa', 
        border: '1px solid #b2f5ea', 
        borderRadius: '8px',
        color: '#285e61'
      }}>
        <p style={{ margin: 0, fontWeight: 'bold' }}>Welcome, Administrator.</p>
        <p style={{ marginTop: '0.5rem' }}>You have full access to manage the system.</p>
      </div>
    </div>
  );
}
